SELECT  FROM demo_record r JOIN sys_user u ON u.id = r.owner_id

  r.owner_id = #{ownerId}
  AND r.title LIKE #{keyword} ESCAPE '!'
  AND r.status = #{status}

ORDER BY r.created_at DESC, r.id DESC

SELECT  FROM demo_record r JOIN sys_user u ON u.id = r.owner_id
WHERE r.id = #{id}
AND r.owner_id = #{ownerId}
